<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import WorkspaceShell from '../components/WorkspaceShell.vue'
import PublicVideoCard from '../components/PublicVideoCard.vue'
import { publicApi, durationLabel } from '../api/public'
import type { PublicVideo } from '../api/public'
import type { SignedMedia } from '../api/creator'
import { formatTime } from '../api/creator'
import { useStudioError } from '../composables/useStudioError'
import { auth } from '../stores/auth'
import type { Comment } from '../api/public'
const id = String(useRoute().params.id); const explain = useStudioError(); const video = ref<PublicVideo>(); const media = ref<SignedMedia>(); const player = ref<HTMLVideoElement>(); const loading = ref(false); const signing = ref(false); const favoriteBusy = ref(false); const favorited = ref<boolean>(); const liked = ref<boolean>(); const likeBusy = ref(false); const error = ref(''); const mediaError = ref(''); const favoriteError = ref(''); const notice = ref(''); const related = ref<PublicVideo[]>([]); const comments = ref<Comment[]>([]); const commentPage = ref(1); const commentTotal = ref(0); const commentLoading = ref(false); const commentBusy = ref(false); const commentText = ref(''); const videoTags = ref<string[]>([]); const relatedLoading = ref(false); const relatedError = ref(''); let activeRequest: AbortController | undefined; let mediaRequest: AbortController | undefined; let relatedRequest: AbortController | undefined; let commentRequest: AbortController | undefined; const lifetime = new AbortController()
function clearMedia() { player.value?.pause(); player.value?.removeAttribute('src'); player.value?.load(); media.value = undefined }
async function load() { activeRequest?.abort(); mediaRequest?.abort(); relatedRequest?.abort(); signing.value = false; clearMedia(); related.value = []; relatedError.value = ''; const controller = new AbortController(); activeRequest = controller; loading.value = true; error.value = ''; video.value = undefined; try { const result = await publicApi.get(id, controller.signal); if (!controller.signal.aborted) { video.value = result; void loadRelated(result); void loadTags() } } catch (failure) { if (!controller.signal.aborted) error.value = explain(failure) } finally { if (!controller.signal.aborted) loading.value = false } }
async function loadComments(next = commentPage.value) { commentRequest?.abort(); const c = new AbortController(); commentRequest = c; commentLoading.value = true; try { const result = await publicApi.comments(id, next, c.signal); if (!lifetime.signal.aborted && !c.signal.aborted) { comments.value = result.items; commentPage.value = result.page; commentTotal.value = result.total } } catch { /* comments are optional */ } finally { if (!lifetime.signal.aborted && !c.signal.aborted) commentLoading.value = false } }
async function addComment() { const content = commentText.value.trim(); if (!content || commentBusy.value) return; commentBusy.value = true; try { await publicApi.addComment(id, content); if (!lifetime.signal.aborted) { commentText.value = ''; await loadComments(1) } } catch (failure) { if (!lifetime.signal.aborted) mediaError.value = explain(failure) } finally { if (!lifetime.signal.aborted) commentBusy.value = false } }
async function removeComment(comment: Comment) { if (!window.confirm('删除这条评论？')) return; try { await publicApi.deleteComment(comment.id); if (!lifetime.signal.aborted) await loadComments() } catch (failure) { if (!lifetime.signal.aborted) mediaError.value = explain(failure) } }
function canDeleteComment(comment: Comment) { return auth.user.value?.role === 'ADMIN' || auth.user.value?.id === comment.userId }
async function loadTags() { try { const result = await publicApi.videoTags(id, lifetime.signal); if (!lifetime.signal.aborted) videoTags.value = result.tags } catch { /* tags are optional */ } }
async function loadRelated(current: PublicVideo) { relatedRequest?.abort(); const controller = new AbortController(); relatedRequest = controller; relatedLoading.value = true; relatedError.value = ''; try { const result = await publicApi.list('', current.categoryId, '', 'latest', 1, controller.signal); if (!controller.signal.aborted) related.value = result.items.filter(item => item.id !== current.id).slice(0, 3) } catch (failure) { if (!controller.signal.aborted) relatedError.value = explain(failure) } finally { if (!controller.signal.aborted) relatedLoading.value = false } }
async function recordView() {
  if (sessionStorage.getItem(`frame-viewed-${id}`)) return
  sessionStorage.setItem(`frame-viewed-${id}`, '1')
  try {
    const result = await publicApi.view(id)
    if (!lifetime.signal.aborted && video.value) video.value = { ...video.value, viewCount: result.viewCount }
  } catch { /* views are best-effort */ }
}
async function play() { if (!video.value || signing.value || loading.value) return; mediaRequest?.abort(); const controller = new AbortController(); mediaRequest = controller; signing.value = true; mediaError.value = ''; clearMedia(); void recordView(); try { const result = await publicApi.media(id, 'SOURCE', controller.signal); if (!controller.signal.aborted) media.value = result } catch (failure) { if (!controller.signal.aborted) mediaError.value = explain(failure) } finally { if (!controller.signal.aborted) signing.value = false } }
async function reportVideo() { const reason = window.prompt('举报原因（1～500 字）')?.trim() ?? ''; if (!reason) return; try { await publicApi.report('VIDEO', id, reason); mediaError.value = ''; notice.value = '举报已提交。' } catch (failure) { if (!lifetime.signal.aborted) mediaError.value = explain(failure) } }
async function likeState() { try { const result = await publicApi.likeState(id, lifetime.signal); if (!lifetime.signal.aborted) liked.value = result.liked } catch { if (!lifetime.signal.aborted) liked.value = undefined } }
async function toggleLike() { if (liked.value === undefined || likeBusy.value) return; const add = !liked.value; likeBusy.value = true; try { await publicApi.like(id, add); if (!lifetime.signal.aborted) { liked.value = add; if (video.value) video.value = { ...video.value, likeCount: Math.max(0, video.value.likeCount + (add ? 1 : -1)) } } } catch { /* best effort */ } finally { if (!lifetime.signal.aborted) likeBusy.value = false } }
async function favoriteState() { favoriteBusy.value = true; favoriteError.value = ''; try { const result = await publicApi.favoriteState(id, lifetime.signal); if (!lifetime.signal.aborted) favorited.value = result.favorited } catch (failure) { if (!lifetime.signal.aborted) { favorited.value = undefined; favoriteError.value = explain(failure) } } finally { if (!lifetime.signal.aborted) favoriteBusy.value = false } }
async function toggleFavorite() { if (favoriteBusy.value || favorited.value === undefined) return; const add = !favorited.value; favoriteBusy.value = true; favoriteError.value = ''; notice.value = ''; try { await publicApi.favorite(id, add); if (!lifetime.signal.aborted) { favorited.value = add; if (video.value) video.value = { ...video.value, favoriteCount: Math.max(0, video.value.favoriteCount + (add ? 1 : -1)) }; notice.value = add ? '已加入收藏。' : '已取消收藏。' } } catch (failure) { if (!lifetime.signal.aborted) { favoriteError.value = `${explain(failure)}。正在核对收藏状态。`; favorited.value = undefined; await favoriteState() } } finally { if (!lifetime.signal.aborted) favoriteBusy.value = false } }
onMounted(() => { if (/^[1-9]\d{0,18}$/.test(id)) { void load(); void favoriteState(); void likeState(); void loadComments() } else error.value = '作品编号无效' }); onBeforeUnmount(() => { lifetime.abort(); activeRequest?.abort(); mediaRequest?.abort(); relatedRequest?.abort(); commentRequest?.abort(); clearMedia() })
</script>
<template><WorkspaceShell><RouterLink class="back-link" to="/">← 发现作品</RouterLink><el-alert v-if="error" :title="error" type="error" :closable="false" role="alert" /><p v-if="loading" class="empty-state" role="status">正在读取作品…</p><el-button v-if="error" @click="load">重新读取</el-button><template v-if="video"><section class="watch-screen" aria-label="视频播放器"><video v-if="media" ref="player" :src="media.url" controls playsinline preload="metadata" @error="mediaError = '视频无法加载或链接已过期，请重新获取播放地址。'" /><div v-else class="watch-prompt"><span>{{ durationLabel(video.durationMillis) }}</span><p>准备观看《{{ video.title }}》</p><el-button :loading="signing" @click="play">加载视频</el-button></div></section><el-alert v-if="mediaError" :title="mediaError" type="error" :closable="false" role="alert" /><div class="watch-toolbar"><span>分类：{{ video.categoryName }} · 作者：{{ video.authorName }}</span><el-button :loading="signing" @click="play">重新获取播放地址</el-button></div><div class="watch-heading"><div><h1>{{ video.title }}</h1><p class="muted"><RouterLink :to="`/authors/${video.authorId}`">{{ video.authorName }}</RouterLink> · {{ video.viewCount }} 次播放 · {{ video.favoriteCount }} 收藏 · {{ video.likeCount }} 赞 · 发布于 {{ formatTime(video.publishedAt) }}</p></div><div class="inline-actions"><el-button :loading="likeBusy" :disabled="liked === undefined" @click="toggleLike">{{ liked ? '已赞' : '点赞' }}</el-button><el-button :loading="favoriteBusy" :disabled="favorited === undefined" @click="toggleFavorite">{{ favorited ? '取消收藏' : '收藏作品' }}</el-button><el-button @click="reportVideo">举报</el-button></div></div><el-alert v-if="favoriteError" :title="favoriteError" type="error" :closable="false" role="alert" /><el-button v-if="favorited === undefined" :disabled="favoriteBusy" @click="favoriteState">查询收藏状态</el-button><p v-if="notice" role="status" class="muted">{{ notice }}</p><div v-if="videoTags.length" class="watch-tags"><RouterLink v-for="item in videoTags" :key="item" :to="{ path: '/', query: { tag: item } }">{{ item }}</RouterLink></div><p class="video-description">{{ video.description || '作者未填写简介。' }}</p><p v-if="media" class="muted">播放地址到期：{{ formatTime(media.expiresAt) }}。过期后可重新获取。</p><section class="studio-panel comment-section"><div class="section-heading"><h2>评论 <span class="count">{{ commentTotal }}</span></h2><el-button :loading="commentLoading" @click="loadComments()">刷新</el-button></div><div class="comment-form"><textarea v-model="commentText" maxlength="500" rows="3" placeholder="说点什么…" :disabled="commentBusy"/><el-button type="primary" :loading="commentBusy" :disabled="!commentText.trim()" @click="addComment">发表评论</el-button></div><article v-for="comment in comments" :key="comment.id" class="history-item"><div class="section-heading"><strong>@{{ comment.username }}</strong><div class="inline-actions"><time>{{ formatTime(comment.createdAt) }}</time><el-button v-if="canDeleteComment(comment)" type="danger" size="small" @click="removeComment(comment)">删除</el-button></div></div><p class="history-reason">{{ comment.content }}</p></article><p v-if="!commentLoading && !comments.length" class="muted">还没有评论。</p><div v-if="commentTotal > 10" class="page-controls"><el-button :disabled="commentLoading || commentPage <= 1" @click="loadComments(commentPage - 1)">上一页评论</el-button><span>第 {{ commentPage }} 页</span><el-button :disabled="commentLoading || commentPage * 10 >= commentTotal || commentPage >= 1000" @click="loadComments(commentPage + 1)">下一页评论</el-button></div></section><section v-if="relatedLoading || related.length || relatedError" class="studio-panel related-section"><div class="related-heading"><h2>同类作品</h2><RouterLink :to="{ path: '/', query: { category: video.categoryId } }">查看全部 →</RouterLink></div><p v-if="relatedLoading" class="muted" role="status">正在读取同类作品…</p><p v-else-if="relatedError" class="muted">同类作品暂时无法加载。</p><div v-else class="public-video-grid related-grid"><PublicVideoCard v-for="item in related" :key="item.id" :video="item" /></div></section></template></WorkspaceShell></template>
